import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SET.md","filePath":"manual-en/SET.md","lastUpdated":1785684581000}'),i={name:"manual-en/SET.md"};function s(r,e,d,p,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_17-20-set" tabindex="-1">17.20 SET <a class="header-anchor" href="#_17-20-set" aria-label="Permalink to &quot;17.20 SET&quot;">​</a></h3><pre><code>SET

(data input)
        /BLANKS={SYSMIS,’.’,number}
        /DECIMAL={DOT,COMMA}
        /FORMAT=fmt_spec
        /EPOCH={AUTOMATIC,year}
        /RIB={NATIVE,MSBFIRST,LSBFIRST,VAX}
        /RRB={NATIVE,ISL,ISB,IDL,IDB,VF,VD,VG,ZS,ZL}

(interaction)
        /MXERRS=max_errs
        /MXWARNS=max_warnings
        /WORKSPACE=workspace_size

(syntax execution)
        /LOCALE=’locale’
        /MXLOOPS=max_loops
        /SEED={RANDOM,seed_value}
        /UNDEFINED={WARN,NOWARN}
        /FUZZBITS=fuzzbits
        /SCALEMIN=count

(data output)
        /CC{A,B,C,D,E}={’npre,pre,suf,nsuf’,’npre.pre.suf.nsuf’}
        /DECIMAL={DOT,COMMA}
        /FORMAT=fmt_spec
        /LEADZERO={ON,OFF}
        /MDISPLAY={TEXT,TABLES}
        /SMALL=number
        /SUMMARY={NONE,comment}
        /WIB={NATIVE,MSBFIRST,LSBFIRST,VAX}
        /WRB={NATIVE,ISL,ISB,IDL,IDB,VF,VD,VG,ZS,ZL}

(output routing)
        /ERRORS={ON,OFF,TERMINAL,LISTING,BOTH,NONE}
        /MESSAGES={ON,OFF,TERMINAL,LISTING,BOTH,NONE}
        /PRINTBACK={ON,OFF,TERMINAL,LISTING,BOTH,NONE}
        /RESULTS={ON,OFF,TERMINAL,LISTING,BOTH,NONE}

(output driver options)
        /HEADERS={NO,YES,BLANK}
        /LENGTH={NONE,n_lines}
        /WIDTH={NARROW,WIDTH,n_characters}
        /TNUMBERS={VALUES,LABELS,BOTH}
        /TVARS={NAMES,LABELS,BOTH}
        /TLOOK={NONE,file}

(logging)
        /JOURNAL={ON,OFF} [’file_name’]

(system files)
        /SCOMPRESSION={ON,OFF}

(miscellaneous)
        /SAFER=ON
        /LOCALE=’string’

(macros)
        /MEXPAND={ON,OFF}
        /MPRINT={ON,OFF}
        /MITERATE=number
        /MNEST=number

(settings not yet implemented, but accepted and ignored)
        /BASETEXTDIRECTION={AUTOMATIC,RIGHTTOLEFT,LEFTTORIGHT}
        /BLOCK=’c’
        /BOX={’xxx’,’xxxxxxxxxxx’}
        /CACHE={ON,OFF}
        /CELLSBREAK=number
        /COMPRESSION={ON,OFF}
        /CMPTRANS={ON,OFF}
        /HEADER={NO,YES,BLANK}
</code></pre><p><code>SET</code> allows the user to adjust several parameters relating to PSPP’s execution. Since there are many subcommands to this command, its subcommands are examined in groups.</p><p>For subcommands that take boolean values, <code>ON</code> and <code>YES</code> are synonymous, as are <code>OFF</code> and <code>NO</code>, when used as subcommand values.</p><p>The data input subcommands affect the way that data is read from data files. The data input subcommands are</p><p>BLANKS</p><p>This is the value assigned to an item data item that is empty or contains only white space. An argument of SYSMIS or ’.’ causes the system-missing value to be assigned to null items. This is the default. Any real value may be assigned.</p><p>DECIMAL</p><p>This value may be set to <code>DOT</code> or <code>COMMA</code>. Setting it to <code>DOT</code> causes the decimal point character to be ‘.’ and the grouping character to be ‘,’. Setting it to <code>COMMA</code> causes the decimal point character to be ‘,’ and the grouping character to be ‘.’. If the setting is <code>COMMA</code>, then ‘,’ is not treated as a field separator in the <code>DATA LIST</code> command (see <a href="./DATA-LIST">DATA LIST</a>). The default value is determined from the system locale.</p><p>FORMAT</p><p>Allows the default numeric input/output format to be specified. The default is F8.2. See <a href="./Input-and-Output-Formats">Input and Output Formats</a>.</p><p>EPOCH</p><p>Specifies the range of years used when a 2-digit year is read from a data file or used in a date construction expression (see <a href="./Date-Construction">Date Construction</a>). If a 4-digit year is specified for the epoch, then 2-digit years are interpreted starting from that year, known as the epoch. If <code>AUTOMATIC</code> (the default) is specified, then the epoch begins 69 years before the current date.</p><p>RIB</p><p>PSPP extension to set the byte ordering (endianness) used for reading data in IB or PIB format (see <a href="./Binary-and-Hexadecimal-Numeric-Formats">Binary and Hexadecimal Numeric Formats</a>). In <code>MSBFIRST</code> ordering, the most-significant byte appears at the left end of a IB or PIB field. In <code>LSBFIRST</code> ordering, the least-significant byte appears at the left end. <code>VAX</code> ordering is like <code>MSBFIRST</code>, except that each pair of bytes is in reverse order. <code>NATIVE</code>, the default, is equivalent to <code>MSBFIRST</code> or <code>LSBFIRST</code> depending on the native format of the machine running PSPP.</p><p>RRB</p><p>PSPP extension to set the floating-point format used for reading data in RB format (see <a href="./Binary-and-Hexadecimal-Numeric-Formats">Binary and Hexadecimal Numeric Formats</a>). The possibilities are:</p><p>NATIVE</p><p>The native format of the machine running PSPP. Equivalent to either IDL or IDB.</p><p>ISL</p><p>32-bit IEEE 754 single-precision floating point, in little-endian byte order.</p><p>ISB</p><p>32-bit IEEE 754 single-precision floating point, in big-endian byte order.</p><p>IDL</p><p>64-bit IEEE 754 double-precision floating point, in little-endian byte order.</p><p>IDB</p><p>64-bit IEEE 754 double-precision floating point, in big-endian byte order.</p><p>VF</p><p>32-bit VAX F format, in VAX-endian byte order.</p><p>VD</p><p>64-bit VAX D format, in VAX-endian byte order.</p><p>VG</p><p>64-bit VAX G format, in VAX-endian byte order.</p><p>ZS</p><p>32-bit IBM Z architecture short format hexadecimal floating point, in big-endian byte order.</p><p>ZL</p><p>64-bit IBM Z architecture long format hexadecimal floating point, in big-endian byte order.</p><p>Z architecture also supports IEEE 754 floating point. The ZS and ZL formats are only for use with very old input files.</p><p>The default is NATIVE.</p><p>Interaction subcommands affect the way that PSPP interacts with an online user. The interaction subcommands are</p><p>MXERRS</p><p>The maximum number of errors before PSPP halts processing of the current command file. The default is 50.</p><p>MXWARNS</p><p>The maximum number of warnings + errors before PSPP halts processing the current command file. The special value of zero means that all warning situations should be ignored. No warnings are issued, except a single initial warning advising you that warnings will not be given. The default value is 100.</p><p>Syntax execution subcommands control the way that PSPP commands execute. The syntax execution subcommands are</p><p>LOCALE</p><p>Overrides the system locale for the purpose of reading and writing syntax and data files. The argument should be a locale name in the general form <code>language_country.encoding</code>, where language and country are 2-character language and country abbreviations, respectively, and encoding is an IANA character set name. Example locales are <code>en_US.UTF-8</code> (UTF-8 encoded English as spoken in the United States) and <code>ja_JP.EUC-JP</code> (EUC-JP encoded Japanese as spoken in Japan).</p><p>MXLOOPS</p><p>The maximum number of iterations for an uncontrolled loop (see <a href="./LOOP">LOOP</a>), and for any loop in the matrix language (see <a href="./Matrix-LOOP-and-BREAK-Commands">Matrix LOOP and BREAK Commands</a>). The default max_loops is 40.</p><p>SEED</p><p>The initial pseudo-random number seed. Set it to a real number or to RANDOM, to obtain an initial seed from the current time of day.</p><p>UNDEFINED</p><p>Currently not used.</p><p>FUZZBITS</p><p>The maximum number of bits of errors in the least-significant places to accept for rounding up a value that is almost halfway between two possibilities for rounding with the RND operator (see <a href="./Miscellaneous-Mathematics">Miscellaneous Mathematics</a>). The default fuzzbits is 6.</p><p>SCALEMIN</p><p>The minimum number of distinct valid values for PSPP to assume that a variable has a scale measurement level. See <a href="./Attributes#Measurement-Level">Measurement Level</a>.</p><p>WORKSPACE</p><p>The maximum amount of memory (in kilobytes) that PSPP uses to store data being processed. If memory in excess of the workspace size is required, then PSPP starts to use temporary files to store the data. Setting a higher value means that procedures run faster, but may cause other applications to run slower. On platforms without virtual memory management, setting a very large workspace may cause PSPP to abort.</p><p>Data output subcommands affect the format of output data. These subcommands are</p><p>CCA CCB CCC CCD CCE</p><p>Set up custom currency formats. See <a href="./Custom-Currency-Formats">Custom Currency Formats</a>, for details.</p><p>DECIMAL</p><p>The default <code>DOT</code> setting causes the decimal point character to be ‘.’. A setting of <code>COMMA</code> causes the decimal point character to be ‘,’.</p><p>FORMAT</p><p>Allows the default numeric input/output format to be specified. The default is F8.2. See <a href="./Input-and-Output-Formats">Input and Output Formats</a>.</p><p>LEADZERO</p><p>Controls whether numbers with magnitude less than one are displayed with a zero before the decimal point. For example, with <code>SET LEADZERO=OFF</code>, which is the default, one-half is shown as 0.5, and with <code>SET LEADZERO=ON</code>, it is shown as .5. This setting affects only the <code>F</code>, <code>COMMA</code>, and <code>DOT</code> formats.</p><p>MDISPLAY</p><p>Controls how the <code>PRINT</code> command within <code>MATRIX</code>…<code>END MATRIX</code> outputs matrices. With the default <code>TEXT</code>, <code>PRINT</code> outputs matrices as text. Change this setting to <code>TABLES</code> to instead output matrices as pivot tables. See <a href="./Matrix-PRINT-Command">Matrix PRINT Command</a>, for more information.</p><p>SMALL</p><p>This controls how PSPP formats small numbers in pivot tables, in cases where PSPP does not otherwise have a well-defined format for the numbers. When such a number has a magnitude less than the value set here, PSPP formats the number in scientific notation; otherwise, it formats it in standard notation. The default is 0.0001. Set a value of 0 to disable scientific notation.</p><p>SUMMARY</p><p>The <code>SUMMARY</code> option sets the comment string which will appear in all generated tables until the next <code>SUMMARY</code> is issued. If the special value <code>NONE</code> is specified, then no comment will appear. These comment strings can be seen in the graphical user interface by placing the pointer over the table. If comment contains any of the following substrings, they will be subsituted as follows:</p><p><code>\\n</code></p><p>A line break.</p><p><code>)DATE</code></p><p>The current date in the form ‘dd-mmm-yyyy’</p><p><code>)ADATE</code></p><p>The current date in the form ‘mm/dd/yyyy’</p><p><code>)SDATE</code></p><p>The current date in the form ‘yyyy/mm/dd’</p><p><code>)EDATE</code></p><p>The current date in the form ‘dd.mm.yyyy’</p><p><code>)TIME</code></p><p>The current 12 hour clock time in the form ‘hh:mm:ss’</p><p><code>)ETIME</code></p><p>The current 24 hour clock time in the form ‘hh:mm:ss’</p><p>WIB</p><p>PSPP extension to set the byte ordering (endianness) used for writing data in IB or PIB format (see <a href="./Binary-and-Hexadecimal-Numeric-Formats">Binary and Hexadecimal Numeric Formats</a>). In <code>MSBFIRST</code> ordering, the most-significant byte appears at the left end of a IB or PIB field. In <code>LSBFIRST</code> ordering, the least-significant byte appears at the left end. <code>VAX</code> ordering is like <code>MSBFIRST</code>, except that each pair of bytes is in reverse order. <code>NATIVE</code>, the default, is equivalent to <code>MSBFIRST</code> or <code>LSBFIRST</code> depending on the native format of the machine running PSPP.</p><p>WRB</p><p>PSPP extension to set the floating-point format used for writing data in RB format (see <a href="./Binary-and-Hexadecimal-Numeric-Formats">Binary and Hexadecimal Numeric Formats</a>). The choices are the same as <code>SET RIB</code>. The default is <code>NATIVE</code>.</p><p>In the PSPP text-based interface, the output routing subcommands affect where output is sent. The following values are allowed for each of these subcommands:</p><p>OFF NONE</p><p>Discard this kind of output.</p><p>TERMINAL</p><p>Write this output to the terminal, but not to listing files and other output devices.</p><p>LISTING</p><p>Write this output to listing files and other output devices, but not to the terminal.</p><p>ON BOTH</p><p>Write this type of output to all output devices.</p><p>These output routing subcommands are:</p><p>ERRORS</p><p>Applies to error and warning messages. The default is <code>BOTH</code>.</p><p>MESSAGES</p><p>Applies to notes. The default is <code>BOTH</code>.</p><p>PRINTBACK</p><p>Determines whether the syntax used for input is printed back as part of the output. The default is <code>NONE</code>.</p><p>RESULTS</p><p>Applies to everything not in one of the above categories, such as the results of statistical procedures. The default is <code>BOTH</code>.</p><p>These subcommands have no effect on output in the PSPP GUI environment.</p><p>Output driver option subcommands affect output drivers’ settings. These subcommands are</p><p>HEADERS LENGTH WIDTH TNUMBERS</p><p>The <code>TNUMBERS</code> option sets the way in which values are displayed in output tables. The valid settings are <code>VALUES</code>, <code>LABELS</code> and <code>BOTH</code>. If <code>TNUMBERS</code> is set to <code>VALUES</code>, then all values are displayed with their literal value (which for a numeric value is a number and for a string value an alphanumeric string). If <code>TNUMBERS</code> is set to <code>LABELS</code>, then values are displayed using their assigned labels if any. (See <a href="./VALUE-LABELS">VALUE LABELS</a>.) If the value has no label, then the literal value is used for display. If <code>TNUMBERS</code> is set to <code>BOTH</code>, then values are displayed with both their label (if any) and their literal value in parentheses.</p><p>TVARS</p><p>The <code>TVARS</code> option sets the way in which variables are displayed in output tables. The valid settings are <code>NAMES</code>, <code>LABELS</code> and <code>BOTH</code>. If <code>TVARS</code> is set to <code>NAMES</code>, then all variables are displayed using their names. If <code>TVARS</code> is set to <code>LABELS</code>, then variables are displayed using their label if one has been set. If no label has been set, then the name is used. (See <a href="./VARIABLE-LABELS">VARIABLE LABELS</a>.) If <code>TVARS</code> is set to <code>BOTH</code>, then variables are displayed with both their label (if any) and their name in parentheses.</p><p>TLOOK</p><p>The <code>TLOOK</code> option sets the style used for subsequent table output. Specifying <code>NONE</code> makes PSPP use the default built-in style. Otherwise, specifying file makes PSPP search for an .stt or .tlo file in the same way as specifying --table-look=file the PSPP command line (see <a href="./Main-Options">Main Options</a>).</p><p>These subcommands affect journaling, also called logging. When journaling is enabled, PSPP writes the commands that it executes, plus any errors or other diagostics that it outputs, to a text file, called the <em>journal</em> file.</p><p>PSPP enables journaling by default when it runs interactively in a terminal or in the PSPPIRE GUI. In the GUI, use Edit → Options… to view or override the default location or to disable journaling. From syntax, use <code>SHOW JOURNAL</code> to see the journal’s location and whether it is enabled.</p><p>JOURNAL LOG</p><p>Specify <code>ON</code> to enable the journal and <code>OFF</code> to disable it. Specify a file name to set the name of the journal file.</p><p>System file subcommands affect the default format of system files produced by PSPP. These subcommands are</p><p>SCOMPRESSION</p><p>Whether system files created by <code>SAVE</code> or <code>XSAVE</code> are compressed by default. The default is <code>ON</code>.</p><p>Security subcommands affect the operations that commands are allowed to perform. The security subcommands are</p><p>SAFER</p><p>Setting this option disables the following operations:</p><ul><li>The <code>ERASE</code> command.</li><li>The <code>HOST</code> command.</li><li>The <code>PERMISSIONS</code> command.</li><li>Pipes (file names beginning or ending with ‘|’).</li></ul><p>Be aware that this setting does not guarantee safety (commands can still overwrite files, for instance) but it is an improvement. When set, this setting cannot be reset during the same session, for obvious security reasons.</p><p>LOCALE</p><p>This item is used to set the default character encoding. The encoding may be specified either as an encoding name or alias (see <a href="http://www.iana.org/assignments/character-sets" target="_blank" rel="noreferrer">http://www.iana.org/assignments/character-sets</a>), or as a locale name. If given as a locale name, only the character encoding of the locale is relevant.</p><p>System files written by PSPP use this encoding. System files read by PSPP, for which the encoding is unknown, are interpreted using this encoding.</p><p>The full list of valid encodings and locale names/alias are operating system dependent. The following are all examples of acceptable syntax on common GNU/Linux systems.</p><pre><code>SET LOCALE=&#39;iso-8859-1&#39;.

SET LOCALE=&#39;ru_RU.cp1251&#39;.

SET LOCALE=&#39;japanese&#39;.
</code></pre><p>Contrary to intuition, this command does not affect any aspect of the system’s locale.</p><p>The following subcommands affect the interpretation of macros.</p><p>MEXPAND</p><p>Controls whether macros are expanded. The default is ON.</p><p>MPRINT</p><p>Controls whether the expansion of macros is included in output. This is separate from whether command syntax in general is included in output. The default is OFF.</p><p>MITERATE</p><p>Limits the number of iterations executed in <code>!DO</code> loops within macros. This does not affect other language constructs such as <code>LOOP</code>. This must be set to a positive integer. The default is 1000.</p><p>MNEST</p><p>Limits the number of levels of nested macro expansions. This must be set to a positive integer. The default is 50.</p><p>The following subcommands are not yet implemented, but PSPP accepts them and ignores the settings.</p><p>BASETEXTDIRECTION BLOCK BOX CACHE CELLSBREAK COMPRESSION CMPTRANS HEADER</p>`,147)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
